contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= v, "need enough balance");

        uint balanceBefore = address(c).balance;
        uint callerBalanceBefore = address(this).balance;

        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balanceAfter = address(c).balance;
        uint callerBalanceAfter = address(this).balance;

        assert(
            (reverted && balanceAfter == balanceBefore && callerBalanceAfter == callerBalanceBefore) ||
            (!reverted && balanceAfter + v == balanceBefore && callerBalanceAfter == callerBalanceBefore + v)
        );
    }

    receive() external payable {}
}

