// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= v);
        uint balanceBefore = address(c).balance;
        uint callerBalanceBefore = address(this).balance;
        bool reverted;
        try c.withdraw(v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balanceAfter = address(c).balance;
        uint callerBalanceAfter = address(this).balance;
        assertTrue((reverted && balanceAfter == balanceBefore && callerBalanceAfter == callerBalanceBefore) ||
            (!reverted && balanceAfter + v == balanceBefore && callerBalanceAfter == callerBalanceBefore + v));
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
